using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ArtisanStaffOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/ArtisanStaffOmenData")]
public class ArtisanStaffOmenData : DrawAdditionalDieOmenData
{
	private const string sentinelsGainEffectID = "SentinelsGainEffect";

	[Header("Artisan Staff")]
	[SerializeField]
	private StartingEffect startingEffect;

	public override void Initialize(OmenInstance omenInstance)
	{
		base.Initialize(omenInstance);
		ReferenceSingleton<MiscOmensHandler>.Instance.SentinelStartingEffectOmenList.Add(startingEffect);
		List<RuntimeCompanion> runtimeCompanions = ReferenceSingleton<AssetsReference>.Instance.CurrentCompanions.RuntimeCompanions;
		for (int i = 0; i < runtimeCompanions.Count; i++)
		{
			bool flag = false;
			for (int j = 0; j < runtimeCompanions[i].StartingEffectsAdded.Count; j++)
			{
				if (runtimeCompanions[i].StartingEffectsAdded[j].Effect == startingEffect.Effect)
				{
					runtimeCompanions[i].StartingEffectsAdded[j].IncreaseEffectAmount(startingEffect.EffectAmount);
					flag = true;
				}
			}
			if (!flag)
			{
				runtimeCompanions[i].StartingEffectsAdded.Add(startingEffect);
			}
		}
		List<GameObject> activeCompanions = ReferenceSingleton<AssetsReference>.Instance.CurrentCompanions.ActiveCompanions;
		for (int k = 0; k < activeCompanions.Count; k++)
		{
			activeCompanions[k].GetComponent<CompanionInitializer>().InitializeCompanionEffects(effectFeedback: false);
		}
	}

	public override void OmenRemoved()
	{
		base.OmenRemoved();
		ReferenceSingleton<MiscOmensHandler>.Instance.SentinelStartingEffectOmenList.Remove(startingEffect);
	}

	public override string OmenConvertedDescription()
	{
		return Smart.Format(base.localizationManager.GetLocalizedString("SentinelsGainEffect"), Smart.Format(base.localizationManager.GetLocalizedInfinity(), startingEffect.Effect.GetEffectName())) + "\n" + GetDrawAdditionalDieDescription(additionalDieAmount);
	}
}
